-- C11 / P11.7 — replaceable publishing provider adapters with explicit Work/owner-browser boundaries and health evidence.
create table if not exists public.command_center_book_publishing_provider_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 provider_event_id text not null check(btrim(provider_event_id)<>''), provider_key text not null check(btrim(provider_key)<>''), version integer not null check(version>0), health text not null check(health in ('available','degraded','unavailable')), capabilities text[] not null check(cardinality(capabilities)>0), implementation_ref text not null check(btrim(implementation_ref)<>''), evidence_refs text[] not null check(cardinality(evidence_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,provider_event_id), unique(owner_id,provider_key,version)
);
create table if not exists public.command_center_book_publishing_provider_boundary_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 boundary_event_id text not null check(btrim(boundary_event_id)<>''), provider_key text not null check(btrim(provider_key)<>''), provider_version integer not null check(provider_version>0), capability text not null check(btrim(capability)<>''), boundary text not null check(boundary in ('normal_chat','work_required','owner_only')), observed_at timestamptz not null,
 primary key(owner_id,boundary_event_id), unique(owner_id,provider_key,provider_version,capability), foreign key(owner_id,provider_key,provider_version) references public.command_center_book_publishing_provider_history(owner_id,provider_key,version) on delete restrict
);
create or replace view public.command_center_book_publishing_providers_current with (security_invoker=true) as select distinct on(owner_id,provider_key) owner_id,provider_event_id,provider_key,version,health,capabilities,implementation_ref,evidence_refs,observed_at from public.command_center_book_publishing_provider_history order by owner_id,provider_key,version desc,observed_at desc;
create or replace function public.command_center_validate_book_provider_boundary() returns trigger language plpgsql set search_path to 'public' as $$
declare caps text[]; begin select capabilities into caps from public.command_center_book_publishing_provider_history p where p.owner_id=new.owner_id and p.provider_key=new.provider_key and p.version=new.provider_version; if caps is null or not(new.capability=any(caps)) then raise exception 'Provider boundary capability must exist in exact adapter version'; end if; return new; end $$;
drop trigger if exists command_center_book_provider_boundary_validate on public.command_center_book_publishing_provider_boundary_history; create trigger command_center_book_provider_boundary_validate before insert on public.command_center_book_publishing_provider_boundary_history for each row execute function public.command_center_validate_book_provider_boundary();
create or replace function public.command_center_reject_book_provider_evidence_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book publishing provider evidence is immutable'; end $$;
drop trigger if exists command_center_book_provider_history_immutable on public.command_center_book_publishing_provider_history; create trigger command_center_book_provider_history_immutable before update or delete on public.command_center_book_publishing_provider_history for each row execute function public.command_center_reject_book_provider_evidence_mutation();
drop trigger if exists command_center_book_provider_boundary_immutable on public.command_center_book_publishing_provider_boundary_history; create trigger command_center_book_provider_boundary_immutable before update or delete on public.command_center_book_publishing_provider_boundary_history for each row execute function public.command_center_reject_book_provider_evidence_mutation();
alter table public.command_center_book_publishing_provider_history enable row level security; alter table public.command_center_book_publishing_provider_boundary_history enable row level security;
revoke all on table public.command_center_book_publishing_provider_history,public.command_center_book_publishing_provider_boundary_history from public,anon,authenticated; grant select,insert on table public.command_center_book_publishing_provider_history,public.command_center_book_publishing_provider_boundary_history to authenticated; grant select on table public.command_center_book_publishing_providers_current to authenticated;
create policy p11_7_book_provider_owner on public.command_center_book_publishing_provider_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_7_book_provider_boundary_owner on public.command_center_book_publishing_provider_boundary_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
